/*! Tenant Restrictions Plugin - AMD Module */
define(['jquery'],function($){return{init:function(allowedCategories){this.filterCategoryDropdowns(allowedCategories),this.filterCourseManagement(allowedCategories)},filterCategoryDropdowns:function(allowedCategories){$('select[name="category"], select[name="categoryid"], select[id*="category"]').each(function(){var $select=$(this),$options=$select.find('option');if(!allowedCategories||allowedCategories.length===0)return;$options.each(function(){var $option=$(this),value=parseInt($option.val());if(value===0||value===''||$option.text().trim()==='')return;if(allowedCategories.indexOf(value)===-1)$option.hide()})})},filterCourseManagement:function(allowedCategories){if(allowedCategories&&allowedCategories.length>0){$('.course_category_tree .category').each(function(){var $category=$(this),categoryId=$category.data('categoryid')||$category.attr('data-categoryid');if(categoryId&&allowedCategories.indexOf(parseInt(categoryId))===-1)$category.hide()})}}}});
